import { createEntryPayload } from "./page";

export const EntriesPage = () => {
  const payload = createEntryPayload({
    entryId: "entry-1",
    name: "Draft",
    tags: ["new"],
    enabled: true,
  });

  return <pre>{JSON.stringify(payload)}</pre>;
};

/**
 * @summary 엔트리 생성 payload 계약
 */
interface CreateEntryPayload {
  /**
   * @field 엔트리 식별자
   */
  entryId: string;
  /**
   * @field 엔트리 이름
   */
  name: string;
  /**
   * @field 엔트리 태그 목록
   */
  tags: string[];
  /**
   * @field 엔트리 활성화 여부
   */
  enabled: boolean;
}

/**
 * @helper 화면 전용 엔트리 생성 payload 정규화
 */
export const createEntryPayload = (
  params: CreateEntryPayload,
): CreateEntryPayload => {
  const { entryId, name, tags, enabled } = params;

  return {
    entryId,
    name: name.trim(),
    tags,
    enabled,
  };
};
